  piernaD: L3('pierna derecha (amputación)', 'right leg (amputation)', 'perna direita (amputação)'), pelvis: L3('pelvis (hemorragia interna)', 'pelvis (internal bleeding)', 'pelve (hemorragia interna)'), cara: L3('cara', 'face', 'face'),
  cuero: L3('cuero cabelludo', 'scalp', 'couro cabeludo'), abdomen: L3('abdomen (interna)', 'abdomen (internal)', 'abdómen (interna)'), torax: L3('tórax (interna)', 'chest (internal)', 'tórax (interna)')
