/* las bajas que llegan ya tratadas en el escenario (el registro y los controles lo reflejan) */
function pretratar(st, esc) {
  esc.bajas.forEach((d, i) => { const b = st.bajas[i];
    b.fuentes.forEach((f, j) => { const df = d.fuentes[j]; if (df.ctlIni) { f.ctl = df.ctlIni; f.tqs = 1; f.marcado = true; } });
    for (const a of d.pretratado || []) { st.log.push({t: 0, a, b: b.id, fase: 'tfc', fuera: false, ok: true, pre: true}); if (a === 'tq') { const f = b.fuentes[0]; f.tqs = 1; f.ctl = .98; f.marcado = true; } if (a === 'io' || a === 'iv') b.acceso = true; if (a === 'txa') b.txa = 1; }
  });
}
const escDe = id => ESC.find(e => e.id === id) || ESC[0];
if (typeof module !== 'undefined') module.exports = {ESC, escDe, pretratar};
